#[inline]
pub unsafe fn htmlEncodeEntities(
    mut out: *mut c_uchar,
    mut outlen: *mut c_int,
    mut in_0: *const c_uchar,
    mut inlen: *mut c_int,
    mut quoteChar: c_int,
) -> c_int {
    if out.is_null() || outlen.is_null() || inlen.is_null() || in_0.is_null() {
        return -(1 as c_int);
    }

    let outstart = out;
    let instart = in_0;
    // SAFETY: outlen/inlen/in_0/out are validated non-null above; pointer arithmetic matches original bounds computation.
    let outend = unsafe { out.add(*outlen as usize) };
    // SAFETY: outlen/inlen/in_0/out are validated non-null above; pointer arithmetic matches original bounds computation.
    let inend = unsafe { in_0.add(*inlen as usize) };
    let mut processed = in_0;

    while in_0 < inend {
        let mut c: c_uint;
        let d0;
        // SAFETY: in_0 < inend is checked by loop condition, so one byte is readable.
        unsafe {
            d0 = *in_0 as c_uint;
            in_0 = in_0.add(1);
        }

        if d0 < 0x80 {
            c = d0;
        } else {
            let trailing: usize;
            if d0 < 0xc0 {
                // SAFETY: out/outstart and processed/instart derive from same allocations as in original code.
                unsafe {
                    *outlen = out.offset_from(outstart) as c_int;
                    *inlen = processed.offset_from(instart) as c_int;
                }
                return -(2 as c_int);
            } else if d0 < 0xe0 {
                c = d0 & 0x1f;
                trailing = 1;
            } else if d0 < 0xf0 {
                c = d0 & 0x0f;
                trailing = 2;
            } else if d0 < 0xf8 {
                c = d0 & 0x07;
                trailing = 3;
            } else {
                // SAFETY: out/outstart and processed/instart derive from same allocations as in original code.
                unsafe {
                    *outlen = out.offset_from(outstart) as c_int;
                    *inlen = processed.offset_from(instart) as c_int;
                }
                return -(2 as c_int);
            }

            // SAFETY: both pointers are within the same input allocation as established above.
            if unsafe { inend.offset_from(in_0) } < trailing as isize {
                break;
            }

            let mut rem = trailing;
            while rem != 0 {
                let d;
                // SAFETY: remaining-byte check above guarantees these continuation bytes are readable.
                unsafe {
                    d = *in_0 as c_uint;
                    in_0 = in_0.add(1);
                }
                if d & 0xc0 != 0x80 {
                    // SAFETY: out/outstart and processed/instart derive from same allocations as in original code.
                    unsafe {
                        *outlen = out.offset_from(outstart) as c_int;
                        *inlen = processed.offset_from(instart) as c_int;
                    }
                    return -(2 as c_int);
                }
                c = (c << 6) | (d & 0x3f);
                rem -= 1;
            }
        }

        if c < 0x80
            && c != quoteChar as c_uint
            && c != '&' as c_uint
            && c != '<' as c_uint
            && c != '>' as c_uint
        {
            if out >= outend {
                break;
            }
            // SAFETY: out < outend checked just above, so one output byte is writable.
            unsafe {
                *out = c as c_uchar;
                out = out.add(1);
            }
        } else {
            let cp: *const c_char;
            let len: c_int;
            let mut nbuf: [c_char; 16] = [0; 16];

            // SAFETY: external lookup preserves original behavior.
            let ent = unsafe { htmlEntityValueLookup(c) };
            if ent.is_null() {
                // SAFETY: nbuf is a valid writable buffer of the provided size; format string and argument match original code.
                unsafe {
                    snprintf(
                        nbuf.as_mut_ptr(),
                        ::core::mem::size_of::<[c_char; 16]>() as size_t,
                        b"#%u\0" as *const u8 as *const c_char,
                        c,
                    );
                }
                cp = nbuf.as_mut_ptr();
                // SAFETY: snprintf writes a NUL-terminated string into nbuf for this format and buffer size.
                len = unsafe { strlen(cp) as c_int };
            } else {
                // SAFETY: ent is non-null and points to a valid htmlEntityDesc as returned by lookup.
                unsafe {
                    cp = (*ent).name;
                    len = strlen(cp) as c_int;
                }
            }

            // SAFETY: outend/out are within the same output allocation.
            if unsafe { outend.offset_from(out) } < (len + 2) as isize {
                break;
            }

            // SAFETY: capacity check above guarantees len + 2 writable bytes at out; cp points to len readable bytes.
            unsafe {
                *out = b'&';
                out = out.add(1);
                memcpy(out as *mut c_void, cp as *const c_void, len as size_t);
                out = out.add(len as usize);
                *out = b';';
                out = out.add(1);
            }
        }

        processed = in_0;
    }

    // SAFETY: out/outstart and processed/instart derive from same allocations as in original code.
    unsafe {
        *outlen = out.offset_from(outstart) as c_int;
        *inlen = processed.offset_from(instart) as c_int;
    }
    0 as c_int
}

